text:
{
  "units": [
    {
      "issue": "截至2023-08-01，在实际交付、合法利息、付款抵充、保证行权及付款后部分债务转移共同作用下，确定A、B、C的剩余债务、各主体责任范围与即时履行条件，并区分债务总额和重叠的保证责任。本单元属于虚构题设下的规则适用与金额核对，不是法院实际判断提取。",
      "decisive_facts": [
        {
          "fact": "A成立于2022年，资金为套取的银行信贷资金；实际交付143140.00元，已返还20330.00元。双方约定如合同无效，已付款全部抵减应返还财产；不请求其他无效后赔偿。",
          "spans": ["S01", "S02", "S12"]
        },
        {
          "fact": "B于2022-01-12实际交付并成立，票面199980.00元中预扣12580.00元，实际收到187400.00元；约定年利率13.20%，题设认可成立时一年期LPR为3.70%。三次结息借据均无新增交付，不构成债务更新。",
          "spans": ["S03", "S04", "S05"]
        },
        {
          "fact": "B保证原件约定戊、庚各自对全部B债务承担连带责任保证，内部相互追偿份额各50%。二人均未书面同意展期；戊于2023-07-07收到完整给付诉状后甲撤诉，庚于2023-07-06独立收到完整给付请求。",
          "spans": ["S06"]
        },
        {
          "fact": "C于2019-02-07实际交付228200.00元并成立，年利率23.50%，到期日2022-12-15。甲请求分段适用利率保护规则，各次起诉时LPR均由题设设定为3.25%；费用1680.00元依法可收取。",
          "spans": ["S07"]
        },
        {
          "fact": "C的T-01至T-07均已到账；T-01截图和收据使用同一交易号，X-01未执行。原合同约定费用、合法利息、本金的清偿顺序，双方仅对T-02另行约定先偿本金；其他单方备注未获甲同意。",
          "spans": ["S08", "S09", "S11"]
        },
        {
          "fact": "己于2022年签署C保证，正文约定乙不能履行、无力偿还时才清偿。甲在2023-06-12撤回对乙的首次起诉后，于2023-06-14再次起诉；截至截日未审判、未执行，乙有可执行财产且无先诉抗辩例外。己后来仅确认收件，没有新保证承诺。",
          "spans": ["S10", "S14"]
        },
        {
          "fact": "SP-01于2023-08-01 09:20实际到账25000.00元，只用于B、C，未指定其中一笔。双方约定在两债均到期且具有同等资信的全额保证时，优先清偿付款日依法可强制请求年利率较高的债务；不存在其他担保。",
          "spans": ["S06", "S13"]
        },
        {
          "fact": "同日13:40，甲乙辛签署文书，约定SP结算后C尚欠各项的50%由辛独自履行，乙退出该部分债务；己未书面同意。16:10追加辛为被告获准，但没有裁判或执行受偿。金额按约定先分项取分，再确定50%份额及余数。",
          "spans": ["S12", "S14"]
        }
      ],
      "support_spans": [
        {
          "span_id": "S01",
          "role": "虚构且无争议的资金来源与交付事实",
          "excerpt": "甲把为个人消费用途向银行套取的信贷资金转给乙；实际到达乙账户143140.00元。"
        },
        {
          "span_id": "S02",
          "role": "附条件清算约定",
          "excerpt": "如A被认定无效，双方同意在清算中全部作为已返还财产冲抵。"
        },
        {
          "span_id": "S03",
          "role": "B本金、成立时间及利率事实",
          "excerpt": "12580.00元在放款当时直接作为预扣利息留在甲账户；乙于2022-01-12实际收到187400.00元。"
        },
        {
          "span_id": "S04",
          "role": "B结息及精度约定",
          "excerpt": "双方不另成立债务更新合同；保留全部计算精度，仅在最终各输出金额上四舍五入到分。"
        },
        {
          "span_id": "S05",
          "role": "B结息凭证",
          "excerpt": "三次归档日期为2022-07-06、2022-10-17、2023-01-09，各次新增交付均为0.00元。"
        },
        {
          "span_id": "S06",
          "role": "B保证原文、独立行权记录与资信事实",
          "excerpt": "戊、庚各自以连带责任保证向甲覆盖全部B债务；庚于2023-07-06实际收到完整给付请求，戊于2023-07-07收到起诉状副本。"
        },
        {
          "span_id": "S07",
          "role": "C成立、利率、费用及计息约定",
          "excerpt": "甲明确请求按照合同成立至2020-08-19当时的司法解释计算该段利息；未付利息不另计息。"
        },
        {
          "span_id": "S08",
          "role": "C已结算付款主表",
          "excerpt": "T-01至T-07分别记载交易号、付款日期、金额及银行已结算状态。"
        },
        {
          "span_id": "S09",
          "role": "双方清偿顺序约定与单方备注的区分",
          "excerpt": "2019-08-23双方又签署仅适用于T-02的补充协议：该笔付款用于清偿本金。"
        },
        {
          "span_id": "S10",
          "role": "C保证条款及程序事件",
          "excerpt": "甲2023-06-14重新对乙起诉C债务，当日有效受理；己签注收到，不确认付款义务。"
        },
        {
          "span_id": "S11",
          "role": "交易去重与执行状态",
          "excerpt": "两份记录的银行交易号均与S08首行相同；X-01未执行，未向甲账户记入该金额。"
        },
        {
          "span_id": "S12",
          "role": "请求范围与单方法律主张",
          "excerpt": "不请求计算保证合同无效后的过错赔偿；所列法律主张不是双方认可的事实或法院认定。"
        },
        {
          "span_id": "S13",
          "role": "SP付款及债务选择约定",
          "excerpt": "2023-08-01 09:20实际付款25000.00元；以付款日依法可强制请求的年利率比较。"
        },
        {
          "span_id": "S14",
          "role": "付款后的主体变更文书",
          "excerpt": "C尚欠各项的50%，此后由辛独自向甲履行；乙对此不再向甲负付款义务；己没有书面同意。"
        },
        {
          "source_id": "civil-code-2020",
          "provisions": ["157", "551", "552", "560", "561", "670", "679", "682", "687", "688", "691", "692", "693", "695", "697", "1260"],
          "role": "返还、抵充、借款成立、保证与债务转移规则",
          "url": "https://www.court.gov.cn/zixun/xiangqing/233181.html"
        },
        {
          "source_id": "lending-2020-12",
          "provisions": ["13", "25", "26", "27", "28", "31"],
          "role": "合同效力、利率限制、结息及过渡规则",
          "url": "https://cicc.court.gov.cn/html/1/380/385/12844.html"
        },
        {
          "source_id": "lending-2015",
          "provisions": ["26"],
          "role": "C旧法期间的利率保护标准",
          "url": "https://www.court.gov.cn/zixun/xiangqing/15146.html"
        },
        {
          "source_id": "guarantee-2020",
          "provisions": ["13", "25", "29", "31", "32", "34", "36"],
          "role": "保证解释、行权相对性、撤诉效果及第三人文书识别",
          "url": "https://www.court.gov.cn/zixun/xiangqing/282721.html"
        }
      ],
      "dependencies": {
        "nodes": [
          {
            "id": "N1",
            "issue": "A效力、返还基数与丁的合同保证责任",
            "fact_refs": ["S01", "S02", "S12"],
            "rule_refs": ["lending-2020-12:13", "civil-code-2020:157", "civil-code-2020:682"],
            "supported_state": "2022年套取银行贷款转贷符合所附无效规则，不以高利或乙知情为必要条件；返还以实际交付减约定已返还财产核对。丁的合同保证随主合同无效，不扩展计算未请求的过错赔偿。"
          },
          {
            "id": "N2",
            "issue": "B实际本金、逐次合法结息与整体上限",
            "fact_refs": ["S03", "S04", "S05", "S06", "S12"],
            "rule_refs": ["civil-code-2020:670", "civil-code-2020:679", "lending-2020-12:25", "lending-2020-12:26", "lending-2020-12:27", "lending-2020-12:28"],
            "supported_state": "以187400.00元实际交付额起算，不以初始票面或后续纸面金额直接替代可保护本金；按13.20%及实际日数逐期核对可资本化利息，再独立比较以最初本金和14.80%计算的整体上限。归档不重置成立时点或LPR。"
          },
          {
            "id": "N3",
            "issue": "B两名保证人的期间、行权和对外范围",
            "fact_refs": ["S06"],
            "rule_refs": ["civil-code-2020:688", "civil-code-2020:691", "civil-code-2020:692", "civil-code-2020:693", "civil-code-2020:695", "guarantee-2020:13", "guarantee-2020:25", "guarantee-2020:29", "guarantee-2020:31", "guarantee-2020:32"],
            "supported_state": "二人均为连带责任保证；保证期间按原到期日计算至2023-07-12，未经同意的展期不延长该期间。戊已于期间内收到诉状，撤诉不抹去该行权；庚另有期间内到达的独立请求。内部各50%不将明确约定的对外全部保证缩减为50%，题设也不支持因未向庚行权而减免戊责任。"
          },
          {
            "id": "N4",
            "issue": "C付款真实性、利率时段与逐笔项目抵充",
            "fact_refs": ["S07", "S08", "S09", "S11"],
            "rule_refs": ["lending-2015:26", "lending-2020-12:25", "lending-2020-12:28", "lending-2020-12:31", "civil-code-2020:561"],
            "supported_state": "按交易号去重，X-01不形成已付款。旧法期间按约定23.50%核算，自2020-08-20起按题设起诉时LPR四倍即13.00%的保护标准核算。2019年付款顺序直接依据当时双方约定；T-02适用双方补充协议，其他单方备注不替代共同约定。每次抵充结果影响后续本金和单利。"
          },
          {
            "id": "N5",
            "issue": "C保证存续与即时履行条件的区分",
            "fact_refs": ["S07", "S10", "S14"],
            "rule_refs": ["civil-code-2020:1260", "civil-code-2020:687", "civil-code-2020:691", "civil-code-2020:692", "civil-code-2020:693", "guarantee-2020:25", "guarantee-2020:31", "guarantee-2020:34"],
            "supported_state": "2022年新成立的保证按其正文识别为一般保证，不能仅因主借款成立于2019年改用旧的保证类型规则。保证期间至2023-06-15；期间内撤诉后于6月14日再诉，支持保证未因期间届满消灭。己仍享有先诉抗辩；收件签名不是新的保证承诺，也不是本次保证存续的必要依据。"
          },
          {
            "id": "N6",
            "issue": "09:20时SP-01在B、C之间的归属及债内抵充",
            "fact_refs": ["S06", "S07", "S09", "S13"],
            "rule_refs": ["civil-code-2020:560", "civil-code-2020:561"],
            "supported_state": "比较对象限定为付款时的B、C。一般保证尚有先诉抗辩不等于无担保；结合存续保证、覆盖范围和资信事实核对S13约定前提。该前提下比较B的13.20%与C依法可请求的13.00%，而非C名义23.50%；再对选定债务进行项目抵充。"
          },
          {
            "id": "N7",
            "issue": "13:40文书的法律性质与乙、辛的责任边界",
            "fact_refs": ["S13", "S14"],
            "rule_refs": ["civil-code-2020:551", "civil-code-2020:552", "guarantee-2020:36"],
            "supported_state": "甲乙辛共同签署、辛独自履行且乙退出相应部分，支持按经债权人同意的部分免责债务转移处理，而非仅凭标题认定保证或债务加入。转移基数为SP结算后的C余额，不新增借款、不重置原利率时点，也不追溯改变09:20的付款抵充。"
          },
          {
            "id": "N8",
            "issue": "部分债务转移对己保证范围的影响",
            "fact_refs": ["S10", "S14"],
            "rule_refs": ["civil-code-2020:687", "civil-code-2020:697"],
            "supported_state": "己未书面同意且无另行约定，对转移给辛的部分不再承担保证责任；对乙保留部分的原一般保证仍须区分存续范围与先诉抗辩，不能据此认定己立即付款或全部保证消灭。"
          },
          {
            "id": "N9",
            "issue": "最终分项、各主体请求额及非重复总额",
            "fact_refs": ["S12", "S14"],
            "rule_refs": ["civil-code-2020:551", "civil-code-2020:687", "civil-code-2020:688", "civil-code-2020:697"],
            "supported_state": "先得到A返还余额、SP后B余额及SP后C各项余额；C按约定分项取分合计，再计算辛的50%及乙承担的余数。乙、辛承担的不同债务份额可以汇总，但同一B余额对应的乙、戊、庚责任不得重复相加；己的存续保证范围不等于即时付款额。"
          }
        ],
        "edges": [
          {
            "from": "N2",
            "to": "N6",
            "dependency": "B合法余额及可请求利率是SP抵充的金额和比较基础。"
          },
          {
            "from": "N3",
            "to": "N6",
            "dependency": "B保证存续与覆盖范围决定付款时担保比较。"
          },
          {
            "from": "N4",
            "to": "N6",
            "dependency": "C逐笔清偿后的余额及受保护利率参与SP比较。"
          },
          {
            "from": "N5",
            "to": "N6",
            "dependency": "C保证是否存续影响担保比较，不能以暂不能执行替代判断。"
          },
          {
            "from": "N6",
            "to": "N7",
            "dependency": "先完成付款抵充，后确定可转移的C余额基数。"
          },
          {
            "from": "N5",
            "to": "N8",
            "dependency": "先确认原一般保证存续和先诉抗辩，再处理范围变化。"
          },
          {
            "from": "N7",
            "to": "N8",
            "dependency": "债务转移而非加入的定性决定未经同意转移部分的保证效果。"
          },
          {
            "from": ["N1", "N2", "N3", "N4", "N6", "N7", "N8"],
            "to": "N9",
            "dependency": "各债务余额、主体变更和保证限制共同决定最终请求口径。"
          }
        ],
        "terminal_node": "N9"
      },
      "answerability": {
        "status": "题设内可回答，尚未形成经复算的金额答案",
        "basis": "主要事实、交易身份、利率参数、清偿约定、保证行权记录和债权人同意均有明确定位；所附条文能够支持主要法律依赖。这里的状态均为题设与规则支持的研究判断，不是裁判认定。",
        "necessary_operations": [
          "交易去重与到账状态核对",
          "合同成立时间和规范适用时段区分",
          "合法结息及独立整体上限比较",
          "保证类型、期间、行权和即时履行条件区分",
          "付款时担保与利率比较",
          "先付款后主体变更的事件顺序核对",
          "债务分项与重叠责任的非重复汇总"
        ],
        "pending_checks": [
          "逐段自然日、十进制金额、利息资本化及整体上限的独立复算",
          "分项取分、50%份额及总额的精度一致性检查",
          "规范摘录和适用版本的独立来源核验",
          "后续学生投影视图的信息充分性与答案泄漏检查"
        ]
      }
    }
  ],
  "rejected_units": [
    {
      "issue": "提取法院已经认定的责任、判付金额或裁判理由",
      "reason": "材料明确为虚构衍生情景，没有可供提取的实体裁判；起诉受理、撤诉许可和追加被告不等于实体请求获支持。",
      "support_spans": ["S10", "S12", "S14"]
    },
    {
      "issue": "计算丁因保证合同无效而应承担的精确过错赔偿",
      "reason": "请求范围明确排除此项，且没有支持具体过错程度、损失及因果关系的事实，不能由保证无效直接生成赔偿比例。",
      "support_spans": ["S01", "S02", "S12"]
    }
  ],
  "limitations": [
    "原案仅为研究动机；不得将其裁判结论、历史轮次参考或source中的机制说明作为本情景实体结论的证据。",
    "所列官方链接、摘录、哈希和抓取状态均来自输入；本阶段未实际访问网页、下载原件或验证哈希。",
    "题设LPR数值属于显著虚构情景中的约定参数，不代表对相应历史月份现实报价的查询结果。",
    "总述称案件于2023-08-01新受理，但S10、S14另载C-诉2于2023-06-14受理、8月1日追加请求，A、B于8月1日新受理。应保留具体事件日期并标注总述口径待统一，不把C首次或再次受理日期改写为8月1日；各次C诉讼LPR相同，当前利率参数未因此出现分歧。",
    "S12中的戊、己、甲、乙意见均为待核验的单方法律主张，不能充当双方约定或已认定事实。",
    "本阶段仅提取主问题和公开可核验的必要依赖，不生成题面、种子、最终训练答案或实测难度标签；未进行盲答、金额复算或发布审核。"
  ]
}
